// DETECT
Node *slow = head, *fast = head;
while (fast && fast->next) {
    slow = slow->next; fast = fast->next->next;
    if (slow == fast) { /* CYCLE */ }
}
// START: reset one to head, walk BOTH 1-step; meet again = entry
slow = head;
while (slow != fast) { slow = slow->next; fast = fast->next; }

